@layer hj.components {
  /* Customise: --hj-combobox-height · --hj-combobox-radius · --hj-combobox-popup-radius · --hj-combobox-list-height */
  .hj-combobox-label {
    font-size: 13px;
    font-weight: 600;
    line-height: 1.3;
    color: var(--hj-fg);
  }

  /* The field box: a lone input, or a group holding chips, input, clear and trigger. */
  .hj-combobox-input,
  .hj-combobox-group {
    --_h: var(--hj-combobox-height, 48px);
    --_ring: var(--hj-line);
    width: 100%;
    min-width: 0;
    min-height: var(--_h);
    border: 0;
    border-radius: var(--hj-combobox-radius, var(--hj-radius-sm));
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--_ring);
    color: var(--hj-fg);
    font: 500 15px / 1.2 var(--hj-font-sans);
    transition:
      box-shadow var(--hj-dur-fast) var(--hj-ease-out),
      background-color var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-combobox-input {
    height: var(--_h);
    padding: 0 14px;
    outline: none;
    caret-color: var(--hj-accent);
  }
  .hj-combobox-input[data-size='sm'] {
    --_h: var(--hj-combobox-height, 40px);
    font-size: 14px;
  }
  .hj-combobox-input[data-size='lg'] {
    --_h: var(--hj-combobox-height, 56px);
    font-size: 16px;
  }
  .hj-combobox-input::placeholder {
    color: var(--hj-fg-mute);
    font-weight: 400;
    opacity: 1;
  }
  .hj-combobox-group {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    padding: 6px 6px 6px 14px;
    cursor: text;
  }
  .hj-combobox-group:has(.hj-combobox-chip) {
    padding-left: 6px;
  }
  .hj-combobox-group .hj-combobox-input {
    flex: 1;
    min-width: 96px;
    height: 34px;
    min-height: 0;
    padding: 0 4px;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }
  .hj-combobox-input:hover:not([data-disabled]):not(:focus-visible),
  .hj-combobox-group:hover:not([data-disabled]):not(:focus-within):not([data-popup-open]) {
    --_ring: color-mix(in srgb, var(--hj-fg) 22%, transparent);
  }
  .hj-combobox-input:focus-visible,
  .hj-combobox-group:focus-within,
  .hj-combobox-group[data-popup-open] {
    --_ring: var(--hj-accent);
    box-shadow: inset 0 0 0 1.5px var(--_ring);
    outline: none;
  }
  .hj-combobox-group .hj-combobox-input:focus-visible {
    box-shadow: none;
  }
  .hj-combobox-input[data-invalid],
  .hj-combobox-group[data-invalid] {
    --_ring: var(--hj-danger);
    box-shadow: inset 0 0 0 1.5px var(--_ring);
    caret-color: var(--hj-danger);
  }
  .hj-combobox-group[data-disabled],
  .hj-combobox-input[data-disabled] {
    background: transparent;
    color: var(--hj-fg-mute);
    cursor: not-allowed;
  }

  .hj-combobox-chips {
    display: contents;
  }
  /* Input chips: a picked value you can take back. */
  .hj-combobox-chip {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    height: 32px;
    padding: 0 4px 0 12px;
    border-radius: var(--hj-radius-pill);
    background: var(--hj-surface-2);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg);
    font-size: 13px;
    font-weight: 600;
    white-space: nowrap;
    outline: none;
    cursor: default;
    animation: hj-combobox-chip-in var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-combobox-chip[data-highlighted],
  .hj-combobox-chip:focus-visible,
  .hj-combobox-chip:focus-within {
    background: var(--hj-accent-soft);
    box-shadow: inset 0 0 0 1px transparent;
    color: var(--hj-accent);
  }
  @keyframes hj-combobox-chip-in {
    from {
      opacity: 0;
      transform: scale(0.86);
    }
  }
  .hj-combobox-chip-remove {
    position: relative;
    display: grid;
    place-items: center;
    width: 24px;
    height: 24px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: var(--hj-fg-mute);
    font-size: 14px;
    line-height: 0;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-combobox-chip-remove::before {
    content: '';
    position: absolute;
    inset: -6px -4px;
  }
  .hj-combobox-chip-remove:hover {
    background: color-mix(in srgb, var(--hj-fg) 8%, transparent);
    color: var(--hj-fg);
  }
  .hj-combobox-chip-remove svg {
    width: 1em;
    height: 1em;
  }

  .hj-combobox-trigger,
  .hj-combobox-clear {
    position: relative;
    display: grid;
    place-items: center;
    flex: none;
    width: 32px;
    height: 32px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: var(--hj-fg-mute);
    font-size: 18px;
    line-height: 0;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }
  .hj-combobox-clear {
    font-size: 15px;
  }
  .hj-combobox-trigger::before,
  .hj-combobox-clear::before {
    content: '';
    position: absolute;
    inset: -6px;
  }
  .hj-combobox-trigger:hover,
  .hj-combobox-clear:hover {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg);
  }
  .hj-combobox-trigger[data-popup-open] {
    color: var(--hj-fg);
    transform: rotate(180deg);
  }
  .hj-combobox-trigger svg,
  .hj-combobox-clear svg {
    width: 1em;
    height: 1em;
  }

  .hj-combobox-positioner {
    z-index: var(--hj-z-popover);
    outline: none;
  }
  .hj-combobox-backdrop {
    position: fixed;
    inset: 0;
  }
  .hj-combobox-popup {
    box-sizing: border-box;
    width: var(--anchor-width);
    max-width: var(--available-width);
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-combobox-popup-radius, var(--hj-radius-md));
    background: var(--hj-surface-2);
    background-clip: padding-box;
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: none;
    transform-origin: var(--transform-origin);
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-combobox-popup[data-starting-style],
  .hj-combobox-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.97);
  }
  .hj-combobox-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }

  .hj-combobox-list {
    box-sizing: border-box;
    max-height: min(var(--hj-combobox-list-height, 320px), var(--available-height));
    padding: 6px;
    overflow-y: auto;
    overscroll-behavior: contain;
    scroll-padding-block: 6px;
    outline: none;
  }
  .hj-combobox-list:empty {
    padding: 0;
  }
  .hj-combobox-item {
    display: grid;
    grid-template-columns: 18px minmax(0, 1fr);
    column-gap: 10px;
    align-items: center;
    min-height: 40px;
    padding: 6px 14px 6px 10px;
    border-radius: var(--hj-radius-xs);
    font-size: 14.5px;
    font-weight: 500;
    line-height: 1.3;
    color: var(--hj-fg);
    cursor: default;
    user-select: none;
    outline: none;
    transition: background-color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-combobox-item[data-highlighted] {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
  }
  .hj-combobox-item[data-selected] .hj-combobox-item-text {
    font-weight: 600;
  }
  .hj-combobox-item[data-disabled] {
    opacity: 0.4;
  }
  .hj-combobox-item-indicator {
    grid-column: 1;
    display: inline-flex;
    font-size: 17px;
    line-height: 0;
    color: var(--hj-accent);
    animation: hj-fade-in var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-combobox-item-indicator svg {
    width: 1em;
    height: 1em;
  }
  .hj-combobox-item-text {
    grid-column: 2;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .hj-combobox-item-description {
    grid-column: 2;
    font-size: 12.5px;
    font-weight: 400;
    line-height: 17px;
    color: var(--hj-fg-mute);
  }
  .hj-combobox-empty:not(:empty) {
    padding: 18px 16px;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--hj-fg-mute);
    text-align: center;
  }
  .hj-combobox-status:not(:empty) {
    padding: 10px 16px 0;
    font-size: 12.5px;
    color: var(--hj-fg-mute);
  }
  .hj-combobox-group-label {
    padding: 10px 10px 4px 38px;
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
    color: var(--hj-fg-mute);
  }
  .hj-combobox-separator {
    height: 1px;
    margin: 6px 4px;
    background: var(--hj-line);
  }
  .hj-combobox-row {
    display: flex;
    gap: 4px;
  }
  .hj-combobox-arrow {
    width: 12px;
    height: 6px;
  }
}

'use client';
import { Combobox as Base } from '@base-ui/react/combobox';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

/** State owner: items, value, multiple, onValueChange, filter. Generic over the item type. */
export const Root: typeof Base.Root = Base.Root;
export const Label: HanjiPart<typeof Base.Label> = part(
  Base.Label,
  'Combobox.Label',
  'hj-combobox-label',
);
export const Value: typeof Base.Value = Base.Value;
/** The field box that holds chips, the input, the clear and the trigger. */
export const InputGroup: HanjiPart<typeof Base.InputGroup> = part(
  Base.InputGroup,
  'Combobox.InputGroup',
  'hj-combobox-group',
);
export const Chips: HanjiPart<typeof Base.Chips> = part(
  Base.Chips,
  'Combobox.Chips',
  'hj-combobox-chips',
);
export const Chip: HanjiPart<typeof Base.Chip> = part(
  Base.Chip,
  'Combobox.Chip',
  'hj-combobox-chip',
);
export const List: HanjiPart<typeof Base.List> = part(
  Base.List,
  'Combobox.List',
  'hj-combobox-list',
);
export const Status: HanjiPart<typeof Base.Status> = part(
  Base.Status,
  'Combobox.Status',
  'hj-combobox-status',
);
export const Empty: HanjiPart<typeof Base.Empty> = part(
  Base.Empty,
  'Combobox.Empty',
  'hj-combobox-empty',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'Combobox.Backdrop',
  'hj-combobox-backdrop',
);
export const Popup: HanjiPart<typeof Base.Popup> = part(
  Base.Popup,
  'Combobox.Popup',
  'hj-combobox-popup',
);
export const Arrow: HanjiPart<typeof Base.Arrow> = part(
  Base.Arrow,
  'Combobox.Arrow',
  'hj-combobox-arrow',
);
export const Item: HanjiPart<typeof Base.Item> = part(
  Base.Item,
  'Combobox.Item',
  'hj-combobox-item',
);
export const Group: HanjiPart<typeof Base.Group> = part(
  Base.Group,
  'Combobox.Group',
  'hj-combobox-group-items',
);
export const GroupLabel: HanjiPart<typeof Base.GroupLabel> = part(
  Base.GroupLabel,
  'Combobox.GroupLabel',
  'hj-combobox-group-label',
);
export const Separator: HanjiPart<typeof Base.Separator> = part(
  Base.Separator,
  'Combobox.Separator',
  'hj-combobox-separator',
);
export const Row: HanjiPart<typeof Base.Row> = part(Base.Row, 'Combobox.Row', 'hj-combobox-row');
export const Collection: typeof Base.Collection = Base.Collection;
export const useFilter: typeof Base.useFilter = Base.useFilter;
export const useFilteredItems: typeof Base.useFilteredItems = Base.useFilteredItems;

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface InputOwnProps {
  /** Heights 40 / 48 / 56 when the input draws its own box (outside an InputGroup). */
  size?: 'sm' | 'md' | 'lg';
}
export interface InputProps extends InputOwnProps, Omit<Base.Input.Props, 'size'> {}

/** The text input. Alone it draws a field box; inside InputGroup it is bare text. */
export function Input(props: InputProps): React.ReactElement {
  const config = useHanjiConfig();
  const { size = 'md', className, ...rest } = withDefaults(config, 'Combobox.Input', props);
  return (
    <Base.Input
      {...rest}
      data-size={size}
      className={cls(config, 'Combobox.Input', 'hj-combobox-input', className)}
    />
  );
}

/** Opens the list. Defaults to the adapter's chevron. */
export function Trigger({ children, className, ...props }: Base.Trigger.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Trigger
      aria-label={children ? undefined : config.strings.more}
      {...props}
      className={cls(config, 'Combobox.Trigger', 'hj-combobox-trigger', className)}
    >
      {children ?? config.icons.chevronDown}
    </Base.Trigger>
  );
}

/** Clears the value and the input. Defaults to ✕ with the localised “Clear” label. */
export function Clear({ children, className, ...props }: Base.Clear.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Clear
      aria-label={config.strings.clear}
      {...props}
      className={cls(config, 'Combobox.Clear', 'hj-combobox-clear', className)}
    >
      {children ?? config.icons.x}
    </Base.Clear>
  );
}

/** Removes its chip. Defaults to ✕; give it an aria-label naming the chip. */
export function ChipRemove({
  children,
  className,
  ...props
}: Base.ChipRemove.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.ChipRemove
      {...props}
      className={cls(config, 'Combobox.ChipRemove', 'hj-combobox-chip-remove', className)}
    >
      {children ?? config.icons.x}
    </Base.ChipRemove>
  );
}

/** The check beside a selected item. */
export function ItemIndicator({
  children,
  className,
  ...props
}: Base.ItemIndicator.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.ItemIndicator
      {...props}
      className={cls(config, 'Combobox.ItemIndicator', 'hj-combobox-item-indicator', className)}
    >
      {children ?? config.icons.check}
    </Base.ItemIndicator>
  );
}

/** Places the popup under the input group, gap 6. */
export function Positioner({
  sideOffset = 6,
  collisionPadding = 8,
  className,
  ...props
}: Base.Positioner.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Positioner
      {...props}
      sideOffset={sideOffset}
      collisionPadding={collisionPadding}
      className={cls(config, 'Combobox.Positioner', 'hj-combobox-positioner', className)}
    />
  );
}

export interface OptionOwnProps {
  /** A second line under the label. */
  description?: React.ReactNode;
}
export interface OptionProps extends OptionOwnProps, Base.Item.Props {}

/** An Item with its check, label and optional second line — the common case. */
export function Option({ children, description, ...props }: OptionProps): React.ReactElement {
  const config = useHanjiConfig();
  const styled = !config.unstyled;
  return (
    <Item {...props}>
      <ItemIndicator />
      <span className={styled ? 'hj-combobox-item-text' : undefined}>{children}</span>
      {description ? (
        <span className={styled ? 'hj-combobox-item-description' : undefined}>{description}</span>
      ) : null}
    </Item>
  );
}

export interface ContentOwnProps {
  /** Shown when nothing matches, e.g. “No artists match ‘kōy’”. */
  empty?: React.ReactNode;
  side?: Base.Positioner.Props['side'];
  align?: Base.Positioner.Props['align'];
  container?: Base.Portal.Props['container'];
  /** The list's children: nodes, or a render function per filtered item. */
  children?: Base.List.Props['children'];
}
export interface ContentProps extends ContentOwnProps, Omit<Base.Popup.Props, 'children'> {}

/** Shorthand for Portal + Positioner + Popup + Empty + List. */
export function Content({
  empty,
  side,
  align,
  container,
  children,
  ...popup
}: ContentProps): React.ReactElement {
  return (
    <Portal container={container}>
      <Positioner side={side} align={align}>
        <Popup {...popup}>
          {empty ? <Empty>{empty}</Empty> : null}
          <List>{children}</List>
        </Popup>
      </Positioner>
    </Portal>
  );
}

export * as Combobox from './combobox.tsx';
export type {
  ContentProps as ComboboxContentProps,
  InputProps as ComboboxInputProps,
  OptionProps as ComboboxOptionProps,
} from './combobox.tsx';
